describe('Search Suggestions Highlighting', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should highlight matching part of search term in suggestions', () => {
    cy.get('[data-testid="search-input"]').type('apple');
    cy.get('[data-testid="suggestion-item"]').should('be.visible');
    cy.get('[data-testid="suggestion-item"]').should('contain', 'apple');
    cy.get('[data-testid="suggestion-item"]').should('have.class', 'highlighted');
    cy.get('[data-testid="suggestion-item"]').should('contain', 'apple');
    cy.get('[data-testid="suggestion-item"]').should('have.attr', 'data-testid', 'suggestion-item');
    cy.get('[data-testid="suggestion-item"]').should('contain', 'apple');
  });

  it('should not highlight when no matching suggestions are found', () => {
    cy.get('[data-testid="search-input"]').type('xyz123');
    cy.get('[data-testid="suggestion-item"]').should('not.exist');
    cy.get('[data-testid="no-suggestions-message"]').should('be.visible');
    cy.get('[data-testid="no-suggestions-message"]').should('contain', 'No suggestions found');
  });
});
